            c2->VpiLineNo(c->VpiLineNo());
            c2->VpiColumnNo(c->VpiColumnNo());
            c2->VpiEndLineNo(c->VpiEndLineNo());
            c2->VpiEndColumnNo(c->VpiEndColumnNo());
