        op->VpiReordered(so->VpiReordered());
        op->VpiFlattened(so->VpiFlattened());
        op->VpiOpStrong(so->VpiOpStrong());
        op->VpiDecompile(so->VpiDecompile());
        op->VpiSize(so->VpiSize());
