                        slang::SVInt wv8 = iv.resize((slang::bitwidth_t)w8);
                        std::string bits8;
                        for (int32_t i8 = w8 - 1; i8 >= 0; i8--)
                            bits8 += (wv8[i8] == slang::logic_t(1)) ? '1' : '0';
